use std::alloc::{GlobalAlloc,Layout,System};use std::sync::atomic::{AtomicBool,AtomicU64,Ordering};use js_runtime::{Runtime,Value,EnvId,JsResult};
struct Counting;static ACTIVE:AtomicBool=AtomicBool::new(false);static ALLOCS:AtomicU64=AtomicU64::new(0);static REALLOCS:AtomicU64=AtomicU64::new(0);static BYTES:AtomicU64=AtomicU64::new(0);
unsafe impl GlobalAlloc for Counting{unsafe fn alloc(&self,layout:Layout)->*mut u8{if ACTIVE.load(Ordering::Relaxed){ALLOCS.fetch_add(1,Ordering::Relaxed);BYTES.fetch_add(layout.size()as u64,Ordering::Relaxed);}unsafe{System.alloc(layout)}}unsafe fn alloc_zeroed(&self,layout:Layout)->*mut u8{if ACTIVE.load(Ordering::Relaxed){ALLOCS.fetch_add(1,Ordering::Relaxed);BYTES.fetch_add(layout.size()as u64,Ordering::Relaxed);}unsafe{System.alloc_zeroed(layout)}}unsafe fn dealloc(&self,p:*mut u8,layout:Layout){unsafe{System.dealloc(p,layout)}}unsafe fn realloc(&self,p:*mut u8,layout:Layout,size:usize)->*mut u8{if ACTIVE.load(Ordering::Relaxed){REALLOCS.fetch_add(1,Ordering::Relaxed);BYTES.fetch_add(size as u64,Ordering::Relaxed);}unsafe{System.realloc(p,layout,size)}}}
#[global_allocator]static ALLOCATOR:Counting=Counting;
fn start(){ALLOCS.store(0,Ordering::Relaxed);REALLOCS.store(0,Ordering::Relaxed);BYTES.store(0,Ordering::Relaxed);ACTIVE.store(true,Ordering::Relaxed)}fn end()->(u64,u64,u64){ACTIVE.store(false,Ordering::Relaxed);(ALLOCS.load(Ordering::Relaxed),REALLOCS.load(Ordering::Relaxed),BYTES.load(Ordering::Relaxed))}

fn gc_rounds(rt:&mut Runtime,_:Value,_:&[Value],parent:EnvId)->JsResult<Value>{let env=rt.child_env(parent);for(name,n)in[("battles",6.0),("warmup",0.0),("battleIndex",0.0)]{rt.declare(env,name,Value::Number(n))?;}for index in 0..8{rt.index_property_key(index);}let input=[Some(Value::Number(1.0));8];let mut steady=(0u64,0u64,0u64);for round in 0..6{start();for _ in 0..128{std::hint::black_box(rt.array(&input));}let counts=end();if round>=3{steady.0+=counts.0;steady.1+=counts.1;steady.2+=counts.2;}rt.assign(env,"battleIndex",Value::Number(round as f64),false)?;rt.collect_native_battle_backedge(env,parent)?;}println!("{{\"case\":\"pooled-steady\",\"enabled\":{},\"arrays\":384,\"allocations\":{},\"reallocations\":{},\"requestedBytes\":{}}}",rt.array_storage_reserve_enabled,steady.0,steady.1,steady.2);Ok(Value::Undefined)}
fn main(){for sparse in[false,true]{for enabled in[false,true]{let mut rt=Runtime::new();rt.array_storage_reserve_enabled=enabled;for index in 0..8{rt.index_property_key(index);}let input=(0..8).map(|i|if sparse&&i%2==1{None}else{Some(Value::Number(i as f64))}).collect::<Vec<_>>();start();for _ in 0..1000{std::hint::black_box(rt.array(&input));}let(a,r,b)=end();println!("{{\"case\":\"fresh\",\"sparse\":{sparse},\"enabled\":{enabled},\"arrays\":1000,\"allocations\":{a},\"reallocations\":{r},\"requestedBytes\":{b}}}");}}for enabled in[false,true]{let mut rt=Runtime::new();rt.array_storage_reserve_enabled=enabled;let f=rt.make_closure(gc_rounds,rt.global_env,0,"__nativeRun");rt.set_function_source(f,&include_str!("../../crates/js-runtime/src/native_battle_run.js").encode_utf16().collect::<Vec<_>>()).unwrap();rt.enable_native_battle_gc();rt.call(f,Value::Undefined,&[]).unwrap();}}
